  "[key, label])); export const SEARCH_HELP = `필터 단축키 • Tab/Enter : 필터 추가 • 빈 검색창 Backspace : 위 필터로 이동 + 제거 • 최소 1개 필터는 유지 검색 문법 기본 • 공백 = AND (모두 매칭) • 예: dark magic → 두 단어 모두 어딘가 있는 결과 연산자 (대문자만 인식) • AND : 둘 다 매칭 예) dark AND magic • OR : 둘 중 하나 예) sword OR knife • NOT : 제외 예) footstep NOT rain 그룹화 • 괄호로 우선순위 지정 • 예) (sword OR knife) AND fight 따옴표 phrase • \"dark magic\" → 그 순서로 붙은 결과만 • 단어 1개에는 따옴표 의미 없음 비고 • 1-2글자 짧은 토큰은 매칭 잘 안 됨 (3글자 이상 권장) • 위 문법은 “전체” 필드 검색에서만 적용`; const PRECISE_HELP = [ \"정확한 검색\", \"\", \"단어를 끝까지 입력해야 매칭됩니다. 일부만 치면 안 나옵니다.\", \"단어 단위라 결과가 더 정확합니다.\", \"\", \"예) 'door' → door · doors 함께 나옴\", \" 'doo' (일부만) → 결과 없음\", \"\", \"끄면(넓게 찾기): 글자 조각으로 찾아 'doo'만 쳐도 나옵니다.\", ].join(\"\\n\"); const nextFilterId = (rows: Array": "[key, label])); export const SEARCH_HELP = `Filter shortcut • Tab/Enter: Add filter • Empty search box Backspace: Move to above filter + remove • Maintain at least 1 filter Search syntax basics • Space = AND (match all) • Example: dark magic → Result operator somewhere in both words (only uppercase letters are recognized) • AND: Match both e.g. dark AND magic • OR: Either e.g.) sword OR knife • NOT: Exclude e.g.) footstep NOT rain Grouping • Priority in parentheses Designation • Example) (sword OR knife) AND fight Quote phrase • \"dark magic\" → Only results in that order • Quotes have no meaning for one word Remarks • Short tokens of 1-2 characters do not match well (3 or more characters are recommended) • The above grammar applies only to “all” field searches`; const PRECISE_HELP = [ \"Accurate search\", \"\", \"For a match to be made, you must enter the entire word. If you type only part of it, it will not come out.\", \"Because it is word-by-word, the results are more accurate.\", \"\", \"Example) 'door' → door · doors appear together\", \" 'doo' (partially) → no results\", \"\", \"Off (broad search): Search by letter fragment and just type 'doo' to get it.\", ].join(\"\\n\"); const nextFilterId = (rows: Array",
